// ─────────────────────────────────────────────────────────────────────────
//  01 · a comparable version★★☆
//  concepts: Comparable · equals/hashCode consistency · parsing
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    static final class Version implements Comparable<Version> {
        private final int major, minor, patch;
        private Version(int major, int minor, int patch) { this.major = major; this.minor = minor; this.patch = patch; }

        /** "1", "1.10" or "2.0.3"; missing parts are 0. */
        static Version parse(String text) {
            if (text == null) throw new IllegalArgumentException("version is required");
            String[] parts = text.split("\\.", -1);
            if (parts.length > 3) throw new IllegalArgumentException("too many parts: " + text);
            int[] n = new int[3];
            for (int i = 0; i < parts.length; i++) {
                if (!parts[i].matches("[0-9]+")) throw new IllegalArgumentException("bad part in " + text);
                n[i] = Integer.parseInt(parts[i]);
            }
            return new Version(n[0], n[1], n[2]);
        }
        @Override public int compareTo(Version o) {
            int c = Integer.compare(major, o.major);
            if (c == 0) c = Integer.compare(minor, o.minor);
            if (c == 0) c = Integer.compare(patch, o.patch);
            return c;
        }
        @Override public boolean equals(Object o) {
            return o instanceof Version v && compareTo(v) == 0;
        }
        @Override public int hashCode() {
            return Objects.hash(major, minor, patch);
        }
        @Override public String toString() {
            return major + "." + minor + "." + patch;
        }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("sorts numerically, not as text", () -> {
            var vs = new ArrayList<>(List.of(Version.parse("1.10"), Version.parse("1.9"), Version.parse("1.2.0")));
            Collections.sort(vs);
            eq(vs.toString(), "[1.2.0, 1.9.0, 1.10.0]");
        });
        test("missing parts are zero, so 1.2 equals 1.2.0", () -> ok(Version.parse("1.2").equals(Version.parse("1.2.0")) && Version.parse("1.2").hashCode() == Version.parse("1.2.0").hashCode(), "1.2 == 1.2.0"));
        test("HashSet and TreeSet agree", () -> eq(List.of(new HashSet<>(List.of(Version.parse("3"), Version.parse("3.0.0"))).size(), new TreeSet<>(List.of(Version.parse("3"), Version.parse("3.0.0"))).size()), List.of(1, 1)));
        test("compareTo orders by major, minor, patch", () -> ok(Version.parse("2.0").compareTo(Version.parse("1.99.99")) > 0 && Version.parse("1.0.1").compareTo(Version.parse("1.0.2")) < 0, "ordering"));
        test("malformed versions are rejected (boundary)", () -> { for (var bad : new String[] { "", "1..2", "1.2.", "1.2.3.4", "-1", "+1", "1.x", "1.2 " }) raises(IllegalArgumentException.class, () -> Version.parse(bad)); raises(IllegalArgumentException.class, () -> Version.parse(null)); });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

drills.explanation:
Store three ints; compare them with `Integer.compare` in priority order, and base equals/hashCode on the same three fields:

```java
@Override public int compareTo(Version o) {
    int c = Integer.compare(major, o.major);
    if (c == 0) c = Integer.compare(minor, o.minor);
    if (c == 0) c = Integer.compare(patch, o.patch);
    return c;
}
@Override public boolean equals(Object o) { return o instanceof Version v && compareTo(v) == 0; }
@Override public int hashCode() { return Objects.hash(major, minor, patch); }
```

Because "1.2" is normalised to patch 0 at parse time, every method sees 1.2.0, so HashSet and TreeSet agree.
